import{_ as r,a,b as t}from"./chunks/OOP2values.BXGNZAUw.js";import{_ as i}from"./chunks/Install17.CwCXrGHM.js";import{_ as o,o as s,c as n,a3 as l}from"./chunks/framework.g9mfNVRQ.js";const g=JSON.parse('{"title":"Libre 2","description":"","frontmatter":{"source_hash":"6cdbd15c0c","source_commit":"7a18e7c"},"headers":[],"relativePath":"fr/troubleshoot/libre2.md","filePath":"fr/troubleshoot/libre2.md"}'),c={name:"fr/troubleshoot/libre2.md"};function p(u,e,d,h,m,v){return s(),n("div",null,[...e[0]||(e[0]=[l('<div class="info custom-block"><p class="custom-block-title">Libre 2 EU</p><p>Seule la version européenne du Libre 2 est prise en charge par xDrip.<br> Si vous voulez utiliser un Libre 2 d&#39;une autre zone géographique, vous pouvez faire envoyer les données à xDrip par <a href="./../install/libre2patch.html">une autre application</a>.</p></div><br><h2 id="patched-app" tabindex="-1">Application patchée <a class="header-anchor" href="#patched-app" aria-label="Permalink to &quot;Application patchée {#patched-app}&quot;">​</a></h2><p>En Europe, vous pouvez construire votre application patchée conformément à la directive 2009/24/CE, art. 6 (l&#39;application peut varier d&#39;un pays à l&#39;autre). L&#39;Allemagne bénéficie d&#39;une exception au chapitre 6 du CLUF de l&#39;application du fabricant.<br> La distribution de l&#39;application patchée n&#39;est pas autorisée.</p><p>Vous trouverez des explications pour générer l&#39;application sur <a href="https://github.com/search" target="_blank" rel="noreferrer">GitHub</a> en recherchant <code>xDrip-Patch</code>.</p><p>Le capteur en cours doit avoir été démarré avec l&#39;application patchée pour que celle-ci puisse s&#39;y connecter.<br> Le Bluetooth de votre téléphone doit avoir été activé et les prérequis de l&#39;application remplis <strong>avant</strong> le démarrage du capteur. Si vous avez démarré un capteur sans que ces prérequis soient remplis, vous ne pourrez peut-être pas activer les alarmes, et donc recevoir les données.</p><p>xDrip recevra automatiquement les données de l&#39;application patchée grâce à la source de données matérielle spécifique <a href="./../install/libre2patch.html">Libre2 (patched App)</a>.</p><h4 id="check-connection" tabindex="-1">Vérifier la connexion <a class="header-anchor" href="#check-connection" aria-label="Permalink to &quot;Vérifier la connexion {#check-connection}&quot;">​</a></h4><p>L&#39;application patchée doit être connectée au capteur pour que xDrip en reçoive les données. En général, lorsqu&#39;elle ne l&#39;est pas, vous voyez un point d&#39;exclamation en haut à gauche.</p><img src="'+r+'" style="zoom:75%;"><p>Si votre système fonctionnait correctement et que cela arrive de manière inattendue, essayez de redémarrer votre téléphone, de le mettre en mode avion, puis de désactiver et réactiver le Bluetooth pour voir s&#39;il retrouve la connexion.</p><p>Scanner le capteur peut être une bonne idée. Si le capteur ne donne pas de données après un scan, il est peut-être défectueux.</p><p>Ouvrir le menu peut vous indiquer les prérequis manquants pour que l&#39;application se connecte au capteur.</p><h4 id="prerequisites-to-connection" tabindex="-1">Prérequis de connexion <a class="header-anchor" href="#prerequisites-to-connection" aria-label="Permalink to &quot;Prérequis de connexion {#prerequisites-to-connection}&quot;">​</a></h4><ul><li>Le service de localisation Android doit être autorisé, <strong>Toujours</strong>. Autorisez toujours l&#39;application patchée (exemple ci-dessous pour xDrip)<br><img src="'+i+'" style="zoom:80%;"></li><li>Le téléphone doit être réglé sur <a href="./../install/prerequisites.html#phone-time-accuracy">date, heure et fuseau horaire automatiques</a></li><li>Au moins une des trois alarmes <strong>doit être activée</strong> dans l&#39;application patchée</li><li>Le Bluetooth doit être <strong>activé</strong></li><li>Les alarmes et rappels (sons) doivent être <strong>autorisés</strong> (Paramètres Android - Applications)</li><li>Les notifications doivent être <strong>autorisées</strong> (Paramètres Android - Applications)</li><li>Les notifications sur l&#39;écran de veille doivent être <strong>autorisées</strong> (Paramètres Android - Applications)</li></ul><br><h2 id="direct-connection" tabindex="-1">Connexion directe <a class="header-anchor" href="#direct-connection" aria-label="Permalink to &quot;Connexion directe {#direct-connection}&quot;">​</a></h2><p>Si vous voulez essayer pour la première fois de connecter xDrip directement à un capteur Libre 2 et que vous n&#39;êtes pas sûr de réussir à faire fonctionner le système, il est fortement recommandé de le faire le dernier jour de votre capteur en cours.<br> xDrip ne cassera pas le capteur, il empêchera seulement l&#39;application du fabricant ou le lecteur de recevoir les alarmes ; si vous en dépendez, vous risquez de vous retrouver avec un capteur qui se comporte comme un Libre 1.</p><p>Plus d&#39;informations sur le Libre 2 direct <a href="./libre2direct.html">ici</a></p><h4 id="prerequisites" tabindex="-1">Prérequis <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prérequis {#prerequisites}&quot;">​</a></h4><p>L&#39;appareil qui a servi à démarrer le capteur doit être isolé (four à micro-ondes, éteint) pour éviter qu&#39;il interfère avec l&#39;appairage de xDrip. Il affichera l&#39;icône de perte de connexion.</p><img src="'+a+'" style="zoom:75%;"><p>Si vous avez installé xDrip sur le téléphone qui a servi à démarrer et scanner le capteur, il est recommandé de désinstaller l&#39;application du fabricant : elle vous empêchera de vous connecter au Bluetooth du capteur et perturbera les scans NFC. Vous pourrez la réinstaller une fois xDrip connecté au capteur ; elle n&#39;aura évidemment plus les alarmes du capteur.</p><p>Si vous ne voulez pas supprimer l&#39;application du fabricant, vous devez désactiver son autorisation de localisation dans les paramètres Android.<br><strong>xDrip doit être autorisé, toujours.<br> L&#39;application du fabricant ne doit JAMAIS être autorisée.</strong></p><p>Notez que si vous gardez l&#39;application du fabricant sur votre téléphone, vous devrez choisir entre elle et xDrip à chaque scan NFC du capteur. Cela peut provoquer des erreurs de lecture dans xDrip.</p><h4 id="sensor-scan-errors" tabindex="-1">Erreurs de scan du capteur <a class="header-anchor" href="#sensor-scan-errors" aria-label="Permalink to &quot;Erreurs de scan du capteur {#sensor-scan-errors}&quot;">​</a></h4><p>Vérifiez que vous avez correctement <a href="./../install/libreNFC.html#configure-nfc">configuré</a> le NFC de xDrip.<br> Le scan prend plus de temps avec xDrip. Une fois l&#39;emplacement de l&#39;antenne NFC de votre téléphone trouvé, placez-vous au bon endroit et ne bougez plus.<br> Vous ne pouvez pas scanner moins de 30 secondes après le scan précédent.</p><h4 id="cannot-connect-to-the-sensor" tabindex="-1">Impossible de se connecter au capteur <a class="header-anchor" href="#cannot-connect-to-the-sensor" aria-label="Permalink to &quot;Impossible de se connecter au capteur {#cannot-connect-to-the-sensor}&quot;">​</a></h4><p>Vérifiez qu&#39;<a href="./../use/OOP.html#oop2">OOP2</a> est installé, activez <a href="./../use/misc.html#oop2">sans calibration</a>, <a href="./../use/stopsensor.html#libre">arrêtez le capteur</a> et recommencez à partir d&#39;<a href="./../install/libre2.html#connect-to-the-sensor">ici</a>.</p><p>Scannez à plusieurs reprises toutes les 2 minutes pendant 10 minutes, puis laissez le système tranquille pendant 20 minutes.</p><p>Après plusieurs scans, vous devriez voir des valeurs dans xDrip.<br> Vous devriez aussi voir des valeurs dans l&#39;application OOP2.</p><img src="'+t+'" style="zoom:74%;"><p>Si vous ne voyez pas de valeurs après le scan :</p><ul><li>Vérifiez bien que vous n&#39;avez <strong>PAS</strong> activé <a href="./../use/misc.html#out-of-process-algorithm">OOP1</a> par erreur</li><li>Vérifiez que xDrip a l&#39;<a href="./../install/install.html#enable-location">accès à la localisation autorisé</a>, <strong>toujours</strong></li><li>Redémarrez votre téléphone et réessayez</li></ul><br><p>Consultez la page de <a href="./librebridge.html">dépannage</a> si nécessaire.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2023.06.15" target="_blank" rel="noreferrer"><em>Dernière modification le 18/06/2023</em></a></p>',38)])])}const z=o(c,[["render",p]]);export{g as __pageData,z as default};
